# Embedded browser extension files for FlashGet
import os
import sys
import base64

EXTENSION_FILES = {
    'background.js': '',
    'manifest.json': '',
    'popup.html': '',
    'popup.js': '',
    'icons/icon128.png': '',
    'icons/icon16.png': 'iVBORw0KGgoAAAANSUhEUgAAABAAAAAQCAYAAAAf8/9hAAAAGUlEQVR4nGNgajn+nxLMMGrAqAGjBgwXAwAM90wfeUjb3QAAAABJRU5ErkJggg==',
    'icons/icon48.png': 'iVBORw0KGgoAAAANSUhEUgAAADAAAAAwCAYAAABXAvmHAAAAY0lEQVR4nO3PsQkAIADAMPF2f/MsPcIhCB26p2OufX5uaEADGtCABjSgAQ1oQAMa0IAGNKABDWhAAxrQgAY0oAENaEADGtCABjSgAQ1oQAMa0IAGNKABDWhAAxrQgAY0oAGvXaoRrS3cW/Z0AAAAAElFTkSuQmCC',
}

def ensure_extension_extracted() -> str:
    """Extract extension files into a persistent directory and return its path."""
    if getattr(sys, "frozen", False):
        base_dir = os.path.dirname(os.path.abspath(sys.executable))
    else:
        base_dir = os.path.dirname(os.path.abspath(__file__))

    target_dir = os.path.join(base_dir, "browser_extension")

    try:
        os.makedirs(target_dir, exist_ok=True)
        test_file = os.path.join(target_dir, ".write_test")
        with open(test_file, "w") as f:
            f.write("1")
        os.remove(test_file)
    except Exception:
        appdata = os.getenv("APPDATA") or os.getenv("LOCALAPPDATA") or os.path.expanduser("~")
        target_dir = os.path.join(appdata, "FlashGet", "browser_extension")
        os.makedirs(target_dir, exist_ok=True)

    for rel_path, b64_data in EXTENSION_FILES.items():
        full_path = os.path.join(target_dir, rel_path.replace("/", os.sep))
        os.makedirs(os.path.dirname(full_path), exist_ok=True)
        if not os.path.exists(full_path) or os.path.getsize(full_path) == 0:
            with open(full_path, "wb") as f:
                f.write(base64.b64decode(b64_data))

    return os.path.abspath(target_dir)
